namespace {bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
struct Resolver{ks::StatePackFieldsTask::Kind operator()(uint32_t)const{return ks::StatePackFieldsTask::Kind{};}bool operator()(uint8_t,uint32_t)const{return true;}};
int main(){try{auto memory=std::make_unique<std::array<uint8_t,1<<24>>();auto&m=*memory;uint64_t graphs=0,phases=0,rejections=0,reads=0,writes=0;uint32_t upperComponents=0,dspComponents=0;
 auto run=[&](auto&service){using T=std::decay_t<decltype(service)>;std::array<uint8_t,sizeof(T)>before{};unsigned n=0;int previous=-1;tracking=true;while(!service.complete()){const auto cost=service.nextClocks(previous);check(cost!=0,"Missing factory phase");std::memcpy(before.data(),&service,sizeof(T));unsigned callbacks=0;auto read=[&](uint32_t raw,unsigned dt){check(dt<=cost,"Factory read deadline");++callbacks;++reads;const auto a=raw&0xffffff;check(a<0xfff000||a>=0xfffc00,"Factory scratch read");if(a==0x400004||a==0x600004)return uint8_t(255);if(a==0x40000a||a==0x60000a)return uint8_t(128);if(a==0x40000e||a==0x60000e)return uint8_t(1);return m[a];};auto write=[&](uint32_t raw,uint8_t v,unsigned dt){check(dt<=cost,"Factory write deadline");++callbacks;++writes;const auto a=raw&0xffffff;check(a<0xfff000||a>=0xfffc00,"Factory scratch write");m[a]=v;previous=a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};check(service.advanceBefore(cost-1,read,write,Resolver{},previous)==0,"Rejected factory budget advanced");check(!callbacks&&!std::memcmp(before.data(),&service,sizeof(T)),"Rejected factory budget changed state");++rejections;check(service.advanceBefore(cost,read,write,Resolver{},previous)==cost,"Factory admitted budget");if(service.effect().write)previous=-1;++phases;check(++n<10000000,"Factory service stalled");}tracking=false;if constexpr(std::is_same_v<T,ks::StateFactoryService>)upperComponents|=service.components();else dspComponents|=service.components();++graphs;};
 for(unsigned seed=0;seed<16;++seed){m.fill(0);for(unsigned n=0;n<256;++n){m[0x33000+n]=uint8_t(seed+n);m[0x81fe00+n]=uint8_t(seed*17+n*19);}m[0x169eb]=uint8_t(seed&1);for(unsigned kind=0;kind<3;++kind){ks::StateFactoryService s(ks::StateFactoryService::Kind(kind),{0x33000});run(s);check(s.summary().loaded,"Factory globals closure");}}
 for(unsigned seed=0;seed<8;++seed){m.fill(0);for(unsigned n=0;n<14;++n)m[0x1535a+n]=uint8_t(seed*37+n);for(unsigned n=0;n<256;++n)m[0x860000+n]=uint8_t(seed+n);for(unsigned kind=0;kind<4;++kind){ks::StateFactoryDspService s(ks::StateFactoryDspService::Kind(kind),{uint32_t(0x33aa|(seed&1?0x08000000:0)),0x860000,uint16_t(seed+1),ks::DspPort::B});run(s);}}
 for(unsigned raw:{0x33000u,0x33001u,0x42033001u,0xffa33000u,0xffdc01u})for(bool byte:{false,true}){m.fill(0);ks::StateFactoryDspService s(ks::StateFactoryDspService::Kind::Stream,{byte?0x080033aa:0x33aau,raw,17,ks::DspPort::A});run(s);check(s.summary().sourceAfter==raw+17*(byte?1:2),"Factory raw32 source alias lost");}
 for(unsigned count:{1u,2048u,2049u,4096u})for(bool byte:{false,true}){m.fill(0);m[0x15140]=uint8_t(count>>8);m[0x15141]=uint8_t(count);m[0x15144]=byte?8:0;ks::StateFactoryDspService s(ks::StateFactoryDspService::Kind::Upload);run(s);check(s.summary().uploaded,"Factory upload closure");}
 for(bool byte:{false,true}){m.fill(0);ks::StateFactoryDspService s(ks::StateFactoryDspService::Kind::Stream,{byte?0x080033aa:0x33aau,0x860000,0,ks::DspPort::B});run(s);check(s.summary().sourceAfter==0x860000+65536*(byte?1:2),"Factory zero-count underflow semantics");}
 for(unsigned alias:{0x42033000u,0xffa33001u,0xffdc01u}){m.fill(0);ks::StateFactoryService s(ks::StateFactoryService::Kind::Provided,{alias});run(s);}
 // The first word is valid; the following effective sample would enter the
 // removed execution scratch area. Refuse it before invoking the resource.
 {m.fill(0);ks::StateFactoryDspService s(ks::StateFactoryDspService::Kind::Stream,{0,0xffeffe,2,ks::DspPort::A});bool rejected=false;unsigned n=0;try{while(!s.complete()){const auto cost=s.nextClocks();s.advanceBefore(cost,[&](uint32_t a,unsigned){check(a<0xfff000||a>=0xfffc00,"Evolving factory guard leaked scratch read");return a==0x400004?uint8_t(255):uint8_t(0);},[](uint32_t,uint8_t,unsigned){},-1);check(++n<1000,"Evolving factory guard stalled");}}catch(const std::logic_error&){rejected=true;}check(rejected,"Evolving factory sample guard absent");}
 uint64_t guards=0;auto peek=[](uint32_t){return uint8_t(0);};for(unsigned bad:{0u,0xffff51u,0xffefffu,0xfff000u,0xfff700u,0x42fff700u}){check(!ks::StateFactoryService::admitted(ks::StateFactoryService::Kind::Provided,{bad},peek),"Provided factory scratch source admitted");check(!ks::StateFactoryDspService::admitted(ks::StateFactoryDspService::Kind::Stream,{0,bad,1,ks::DspPort::A},peek),"Factory sample scratch source admitted");guards+=2;}
 check(upperComponents==31&&dspComponents==63&&!allocations,"Factory component/allocation closure");std::cout<<"PASS Factory pure graphs="<<graphs<<" phases="<<phases<<" budgetRejections="<<rejections<<" reads="<<reads<<" writes="<<writes<<" guards="<<guards<<" components="<<upperComponents<<'/'<<dspComponents<<" allocations="<<allocations<<" sizeof="<<sizeof(ks::StateFactoryService)<<'/'<<sizeof(ks::StateFactoryDspService)<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
